var r=[{title:`Höftens rörelser`,text:`Höftflexion för låret mot bålen, och extension tar det bakåt. Leden roterar också inåt och utåt och för benet över eller bort från kroppen. Vardagsrörelser kombinerar flera riktningar, så en tåberöring framåt berättar bara en del av historien.`},{title:`Övningar att prova`,text:`En bekväm höftböjarstretch på ett knä utforskar extension medan du håller bäckenet kontrollerat. Försiktiga 90/90-höftrotationer eller sittande rotationsövningar tränar rotation, och ett stött sidoutfall utforskar innerlårets (adduktorernas) längd och kontroll. Börja långsamt och håll i ett stöd om balansen känns ostadig.`},{title:`Höfterna i dina lyft`,text:`Knäböj kräver att höfter och fotleder rör sig tillsammans. Höftfällningar kräver höftflexion med kontrollerad bål. I en split-knäböj sträcks ena höften medan den andra böjs. Om en djup knäböj känns obekväm kan en annan fotställning, ett grundare djup, hälstöd eller att sätta sig ner mot en stol lösa det snabbare än att tvinga fram en stretch.`},{title:`Allas höfter är olika`,text:`Höftledens form, träningshistorik, nuvarande styrka och ledtolerans påverkar alla ditt omfång. En asymmetri är inte automatiskt en defekt, och samma stretch hör inte hemma i varje program. Avbryt varje övning som orsakar nypande, skarp ledsmärta eller symtom som dröjer sig kvar, och träffa en läkare eller fysioterapeut vid behov.`},{title:`Följ framstegen`,text:`Gör några fokuserade höftövningar före pass där en rörelse har nytta av dem. Mät framstegen utifrån hur säkra och mjuka dina knäböj, höftfällningar och utfall känns, och lämna maximalt stretchdjup åt sidan.`}];var n=[{label:`ACE 2026: rörlighet jämfört med flexibilitet`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`ACE:s övningsbibliotek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`ACSM:s ställningstagande 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var a={sections:r,sources:n};export{a as default,r as sections,n as sources};